// Labeler trial v3: MiniRBT-H256 span labeler on browser CPU (ONNX Runtime
// Web 1.30.0 direct), marking ITEM/TGT character spans in player actions.
//
// DATA CONTRACT: all batches load from artifacts/benchmark/span-labeler-corpus.json
// (generated by train-span-labeler.py); the report records the file's sha256
// plus model file hashes, so Python and browser literally score the same bytes.
// The sealed acceptance batch is evaluated EXACTLY ONCE — only with
// --with-acceptance; without the flag it is loaded NOWHERE and the gate
// reports "not-evaluated". Gates (pre-registered, unchanged): per-field
// strict >= 90% AND e2e <= 4s on that batch; both-fields-correct rate is
// reported but not gating.
//
// DECODING COMPARISON (this round, weights+data frozen): every case is
// decoded twice on the SAME logits —
//   greedy      per-token argmax + first-group-wins span decode (current)
//   constrained whole-sentence argmax under constraints: each field at most
//               one contiguous token range (B- head, I- continuation, empty
//               allowed), spans may not overlap; exact enumeration of all
//               candidate ranges on the five-class probabilities (ties ->
//               first enumerated: null, then i asc, j asc; Python mirrors
//               this exactly in train-span-labeler.py constrained_decode).
// Per-token records on dev batches now keep ALL FIVE class probabilities.
// Diagnosis is MULTI-LABEL (taxonomy in the manifest's errorTaxonomy): one
// gold span can carry several defect classes (e.g. truncated-o AND
// truncated-b), so the reported cut location can't be mispointed by a
// single primary class. Arm differences are surfaced per CASE (armDiffs):
// identical batch scores can hide different predictions when both arms are
// wrong differently (指南针句: q8 TGT=针 vs fp32=校准方).
//
// Timing scope: BOTH decode paths are timed end-to-end per call — raw text
// -> tokenize -> feed -> run -> post-process -> substrings, each mode with
// its own REPEATS+1 loop and median (row.wallMs = {greedy, constrained};
// row 0 of each loop is warm-up). Greedy post-process is argmax + span
// decode; constrained post-process is softmax + whole-sentence enumeration.
// The acceptance gate scores AND times only ACCEPTED_DECODE (recorded in
// the report as decodingMode) — no hardcoded row.greedy in gate code.
// Threads: single-thread only; >1-thread session create hangs in this
// environment (documented in run-classifier-trial.mjs).
//
// Usage: node scripts/run-labeler-trial.mjs [--with-acceptance]
// Output: artifacts/benchmark/labeler-trial-<ts>-spans.json

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { chromium } from "@playwright/test";

const frontendRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const baseUrl = process.env.BASE_URL ?? "http://localhost:3100";
const TARGET_MS = 4000;
const REPEATS = 10;
const CREATE_TIMEOUT_MS = 30000;

const MODEL_DIR = "/models/minirbt-h256-span";
const MODEL_ROOT = path.join(frontendRoot, "public", "models", "minirbt-h256-span");
const MANIFEST_PATH = path.join(frontendRoot, "..", "artifacts", "benchmark", "span-labeler-corpus.json");
const TAGS = ["O", "B-ITEM", "I-ITEM", "B-TGT", "I-TGT"];
// 诊断类别规范序（与 manifest.errorTaxonomy / Python ERROR_CLASSES 一致）。
const CLASS_ORDER = [
  "ok", "span-false", "span-missing", "all-o", "truncated-o", "truncated-b",
  "wrong-field", "over-extended", "boundary-mismatch", "modifier-as-head", "displaced",
];

// 被验收的解码方式：验收门控的 strict 评分与端到端计时只读这一模式
// （row[ACCEPTED_DECODE] / row.wallMs[ACCEPTED_DECODE]），并作为
// decodingMode 显式写进报告。约束解码本轮保留为候选（对照轮收益成立但
// 引入空字段误报），未被设为默认；晋升时只改这一处并按协议重跑验收批。
const ACCEPTED_DECODE = "greedy";

const sha256 = (buffer) => createHash("sha256").update(buffer).digest("hex");

const log = (...parts) => console.log(new Date().toISOString().slice(11, 19), ...parts);

async function main() {
  const evalAcceptance = process.argv.includes("--with-acceptance");

  // ── 唯一数据源：语料 manifest（Python 训练脚本生成）。───────
  const manifestBytes = await readFile(MANIFEST_PATH);
  const manifest = JSON.parse(manifestBytes.toString("utf-8"));
  for (const key of ["devClassic", "devGroups", "scored", "acceptance", "counts", "errorTaxonomy", "acceptanceProtocol"]) {
    if (!manifest[key]) {
      console.error(`FATAL: ${MANIFEST_PATH} is missing "${key}" — regenerate it via train-span-labeler.py --export-corpus`);
      process.exit(2);
    }
  }
  const dataSha = sha256(manifestBytes);
  log(`data: ${path.relative(frontendRoot, MANIFEST_PATH)} sha256=${dataSha.slice(0, 16)}…`);
  log(`sealed acceptance: ${manifest.acceptance.reduce((n, g) => n + g.sentences.length, 0)} sentences -> ${evalAcceptance ? "WILL be evaluated (single-shot per protocol)" : "NOT evaluated (flag --with-acceptance absent)"}`);

  const modelFiles = {};
  for (const rel of ["onnx/model.onnx", "onnx/model_quantized.onnx", "vocab.txt", "config.json"]) {
    try {
      const buf = await readFile(path.join(MODEL_ROOT, rel));
      modelFiles[rel] = { size: buf.length, sha256: sha256(buf) };
    } catch {
      modelFiles[rel] = null;
    }
  }

  const cpu = os.cpus()[0]?.model ?? "unknown";
  log(`host CPU: ${cpu}`);

  const browser = await (async () => {
    try {
      return await chromium.launch({ channel: "msedge", headless: true });
    } catch {
      return chromium.launch({ headless: true });
    }
  })();
  const page = await browser.newPage();
  await page.goto(`${baseUrl}/benchmark`);
  await page.waitForLoadState("domcontentloaded");
  const isolated = await page.evaluate(() => window.crossOriginIsolated === true);
  const userAgent = await page.evaluate(() => navigator.userAgent);
  log(`crossOriginIsolated: ${isolated}`);
  if (!isolated) {
    console.error("FATAL: not cross-origin isolated; wasm multithread unavailable.");
    await browser.close();
    process.exit(2);
  }

  // 评估批：devClassic/devGroups/scored 恒评；封存验收批仅在显式 flag 下
  // 交给浏览器（协议：恰评一次）。
  const batches = [
    { name: "devClassic", rows: manifest.devClassic, tokens: true },
    { name: "devGroups", rows: manifest.devGroups.flatMap((g) => g.sentences.map((s) => ({ ...s, group: g.group }))), tokens: true },
    { name: "scored", rows: manifest.scored, tokens: false },
  ];
  if (evalAcceptance) {
    batches.push({ name: "acceptance", rows: manifest.acceptance.flatMap((g) => g.sentences.map((s) => ({ ...s, group: g.group }))), tokens: false });
  }

  const armConfigs = [
    { name: "q8-t1", threads: 1, file: "onnx/model_quantized.onnx" },
    { name: "fp32-t1", threads: 1, file: "onnx/model.onnx" },
  ];
  const arms = [];
  for (const armConfig of armConfigs) {
    const armPage = await browser.newPage();
    await armPage.goto(`${baseUrl}/benchmark`);
    await armPage.waitForLoadState("domcontentloaded");
    const arm = await armPage.evaluate(
      async ({ modelDir, tags, classOrder, batches, threads, file, repeats, targetMs, timeoutMs }) => {
        const ort = await import("/ort/ort.bundle.min.mjs");
        ort.env.wasm.wasmPaths = "/ort/";
        ort.env.wasm.numThreads = threads;

        const vocabText = await fetch(`${window.location.origin}${modelDir}/vocab.txt`).then((r) => r.text());
        const vocab = new Map();
        vocabText.split("\n").forEach((line, index) => vocab.set(line.replace(/\r$/, ""), index));

        // 分词并保留每 token 的字符区间（与 Python 的 offset_mapping 对齐：
        // 特殊 token 为 [0,0)；中文逐字；ASCII 段最长 wordpiece，piece 自带
        // 前缀"##"的字符数即其区间宽度）。
        const tokenizeWithOffsets = (text, maxLen = 48) => {
          const ids = [vocab.get("[CLS]")];
          const offsets = [[0, 0]];
          let asciiRun = null; // 审查修正：此前初始化为数组、后面却按对象用，英文首段必坏
          const flushAscii = () => {
            if (!asciiRun) return;
            const { word, start: base } = asciiRun;
            asciiRun = null;
            let start = 0;
            while (start < word.length && ids.length < maxLen - 1) {
              let end = word.length;
              let id = null;
              while (end > start) {
                const piece = start === 0 ? word.slice(start, end) : "##" + word.slice(start, end);
                if (vocab.has(piece)) {
                  id = vocab.get(piece);
                  break;
                }
                end -= 1;
              }
              if (id === null) {
                id = vocab.get("[UNK]");
                end = start + 1;
              }
              ids.push(id);
              offsets.push([base + start, base + end]);
              start = end;
            }
          };
          const chars = [...text];
          for (let index = 0; index < chars.length; index += 1) {
            const raw = chars[index];
            const ch = raw.toLowerCase();
            if (/\s/.test(ch)) {
              flushAscii();
              continue;
            }
            if (/[a-z0-9]/.test(ch)) {
              if (!asciiRun) asciiRun = { word: "", start: index };
              asciiRun.word += ch;
              continue;
            }
            flushAscii();
            if (ids.length >= maxLen - 1) break;
            ids.push(vocab.has(ch) ? vocab.get(ch) : vocab.get("[UNK]"));
            offsets.push([index, index + 1]);
          }
          flushAscii();
          ids.push(vocab.get("[SEP]"));
          offsets.push([0, 0]);
          return { ids: ids.slice(0, maxLen), offsets: offsets.slice(0, maxLen) };
        };

        // 与 train-span-labeler.py 的 tags_to_spans 同逻辑（组尾取组内最后
        // 片段的结束位置，而非下一个 token 的起点——句末特殊标记起点是 0）。
        const decodeSpans = (offsets, tagIds) => {
          const spans = { ITEM: null, TGT: null };
          let current = null;
          const flush = () => {
            if (current !== null && spans[current.type] === null) {
              spans[current.type] = [current.start, current.end];
            }
            current = null;
          };
          tagIds.forEach((tagId, index) => {
            const [tokenStart, tokenEnd] = offsets[index];
            const tag = tokenEnd === 0 || tagId >= tags.length ? "O" : tags[tagId];
            if (tag.startsWith("I-") && current !== null && current.type === tag.slice(2)) {
              current.end = tokenEnd;
              return;
            }
            flush();
            if (tag !== "O") current = { type: tag.slice(2), start: tokenStart, end: tokenEnd };
          });
          flush();
          return { ITEM: spans.ITEM, TGT: spans.TGT };
        };

        // 整句约束解码（与 Python constrained_decode 同口径、同枚举顺序）：
        // 每字段至多一段（B- 头、I- 延续、允许空），两段不重叠，最大化整句
        // 对数概率；平局取先枚举者（空 > i 升 > j 升）。
        const constrainedDecode = (offsets, probs) => {
          const idx = [];
          for (let i = 0; i < offsets.length; i += 1) {
            if (offsets[i][1] !== 0) idx.push(i);
          }
          const n = idx.length;
          const ids = new Array(offsets.length).fill(0);
          if (n === 0) return { itemSpan: null, targetSpan: null, ids };
          const lp = (t, c) => Math.log(Math.max(probs[t][c], 1e-12));
          const options = (field) => {
            const bTag = tags.indexOf(`B-${field}`);
            const iTag = tags.indexOf(`I-${field}`);
            const oTag = tags.indexOf("O");
            const opts = [{ gain: 0, a: null, b: null }];
            for (let x = 0; x < n; x += 1) {
              let gain = lp(idx[x], bTag) - lp(idx[x], oTag);
              for (let y = x; y < n; y += 1) {
                if (y > x) gain += lp(idx[y], iTag) - lp(idx[y], oTag);
                opts.push({ gain, a: x, b: y });
              }
            }
            return opts;
          };
          const itemOpts = options("ITEM");
          const tgtOpts = options("TGT");
          let best = null;
          for (const itemOpt of itemOpts) {
            for (const tgtOpt of tgtOpts) {
              if (itemOpt.a !== null && tgtOpt.a !== null && itemOpt.a <= tgtOpt.b && tgtOpt.a <= itemOpt.b) continue;
              const total = itemOpt.gain + tgtOpt.gain;
              if (best === null || total > best.total) best = { total, itemOpt, tgtOpt };
            }
          }
          const assignment = new Array(n).fill("O");
          for (const [opt, field] of [[best.itemOpt, "ITEM"], [best.tgtOpt, "TGT"]]) {
            if (opt.a === null) continue;
            assignment[opt.a] = `B-${field}`;
            for (let t = opt.a + 1; t <= opt.b; t += 1) assignment[t] = `I-${field}`;
          }
          for (let k = 0; k < n; k += 1) ids[idx[k]] = tags.indexOf(assignment[k]);
          return {
            itemSpan: best.itemOpt.a === null ? null : [offsets[idx[best.itemOpt.a]][0], offsets[idx[best.itemOpt.b]][1]],
            targetSpan: best.tgtOpt.a === null ? null : [offsets[idx[best.tgtOpt.a]][0], offsets[idx[best.tgtOpt.b]][1]],
            ids,
          };
        };

        // 与 train-span-labeler.py 的 diagnose_field 同口径：多标签列表，
        // 规范序 classOrder，无缺陷返回 ["ok"]。
        const diagnoseField = (text, gold, pred, otherGold, tokenRows, field, other) => {
          const classes = [];
          if (gold === null) {
            if (pred === null) return ["ok"];
            classes.push("span-false");
            if (otherGold !== null && pred[0] < otherGold[1] && otherGold[0] < pred[1]) classes.push("wrong-field");
            return classes;
          }
          const goldTokens = tokenRows.filter((row) => row.start < gold[1] && gold[0] < row.end);
          const mine = [`B-${field}`, `I-${field}`];
          const theirs = [`B-${other}`, `I-${other}`];
          const preds = goldTokens.map((row) => row.pred);
          if (preds.every((p) => p === "O")) classes.push("all-o");
          else if (preds.some((p) => p === "O") && preds.some((p) => mine.includes(p))) classes.push("truncated-o");
          if (goldTokens.some((row) => row.gold === `I-${field}` && row.pred === `B-${field}`)) classes.push("truncated-b");
          if (preds.some((p) => theirs.includes(p))) classes.push("wrong-field");
          if (pred === null) {
            classes.push("span-missing");
            return [...classes].sort((a, b) => classOrder.indexOf(a) - classOrder.indexOf(b));
          }
          if (pred[0] === gold[0] && pred[1] === gold[1]) return ["ok"];
          if (pred[0] < gold[1] && gold[0] < pred[1]) {
            classes.push(gold[0] >= pred[0] && pred[1] >= gold[1] ? "over-extended" : "boundary-mismatch");
            return [...classes].sort((a, b) => classOrder.indexOf(a) - classOrder.indexOf(b));
          }
          if (otherGold !== null && pred[0] < otherGold[1] && otherGold[0] < pred[1]) classes.push("wrong-field");
          if (pred[1] <= gold[0] && (text.slice(pred[1], gold[0]).includes("的") || text.slice(pred[0], pred[1]).endsWith("的"))) {
            classes.push("modifier-as-head");
          } else {
            classes.push("displaced");
          }
          return [...classes].sort((a, b) => classOrder.indexOf(a) - classOrder.indexOf(b));
        };

        const config = await fetch(`${window.location.origin}${modelDir}/config.json`).then((r) => r.json());
        const id2tag = config.id2label ?? null;
        const tagIndexLookup = (mapping, index) => {
          const tag = mapping[String(index)];
          return tags.indexOf(tag) >= 0 ? tags.indexOf(tag) : 0;
        };

        // 推理共用前缀（两种解码的计时都从这里开始）：分词 -> feed -> run，
        // 返回同一 logits，之后各走各的后处理——两条计时路径的共享部分
        // 一致，差异只在各自的解码方式上。
        const infer = (session, text) => {
          const { ids, offsets } = tokenizeWithOffsets(text);
          const feed = {
            input_ids: new ort.Tensor("int64", BigInt64Array.from(ids.map(BigInt)), [1, ids.length]),
            attention_mask: new ort.Tensor("int64", BigInt64Array.from({ length: ids.length }, () => 1n), [1, ids.length]),
            token_type_ids: new ort.Tensor("int64", BigInt64Array.from({ length: ids.length }, () => 0n), [1, ids.length]),
          };
          return session.run(feed).then((output) => ({
            offsets,
            logits: output.logits.data, // [seq, tags] Float32Array
            seq: output.logits.dims[1],
            tagCount: output.logits.dims[2],
          }));
        };

        // 贪心全路径：argmax -> 首组胜出 span decode -> substrings。
        const greedyFromLogits = (text, { offsets, logits, seq, tagCount }) => {
          const tagIds = [];
          for (let index = 0; index < seq; index += 1) {
            let best = 0;
            let bestValue = -Infinity;
            for (let tagIndex = 0; tagIndex < tagCount; tagIndex += 1) {
              const value = logits[index * tagCount + tagIndex];
              if (value > bestValue) {
                bestValue = value;
                best = tagIndex;
              }
            }
            tagIds.push(id2tag ? tagIndexLookup(id2tag, best) : best);
          }
          const spans = decodeSpans(offsets, tagIds);
          return {
            offsets,
            tagIds,
            itemSpan: spans.ITEM,
            targetSpan: spans.TGT,
            predItem: spans.ITEM !== null ? text.slice(spans.ITEM[0], spans.ITEM[1]) : null,
            predTarget: spans.TGT !== null ? text.slice(spans.TGT[0], spans.TGT[1]) : null,
          };
        };

        // 约束全路径：softmax -> 整句枚举 span decode -> substrings。
        const constrainedFromLogits = (text, { offsets, logits, seq, tagCount }) => {
          const probs = [];
          for (let index = 0; index < seq; index += 1) {
            let sum = 0;
            for (let tagIndex = 0; tagIndex < tagCount; tagIndex += 1) {
              sum += Math.exp(logits[index * tagCount + tagIndex]);
            }
            const row = [];
            for (let tagIndex = 0; tagIndex < tagCount; tagIndex += 1) {
              row.push(Math.exp(logits[index * tagCount + tagIndex]) / sum);
            }
            probs.push(row);
          }
          const decoded = constrainedDecode(offsets, probs);
          return {
            offsets,
            ids: decoded.ids,
            probs,
            itemSpan: decoded.itemSpan,
            targetSpan: decoded.targetSpan,
            predItem: decoded.itemSpan !== null ? text.slice(decoded.itemSpan[0], decoded.itemSpan[1]) : null,
            predTarget: decoded.targetSpan !== null ? text.slice(decoded.targetSpan[0], decoded.targetSpan[1]) : null,
          };
        };

        const createStarted = performance.now();
        let session;
        try {
          session = await Promise.race([
            ort.InferenceSession.create(`${window.location.origin}${modelDir}/${file}`, {
              executionProviders: ["wasm"],
            }),
            new Promise((_, reject) => setTimeout(() => reject(new Error("CREATE-HANG")), timeoutMs)),
          ]);
        } catch (error) {
          if (error.message === "CREATE-HANG") {
            return { status: "create-hung", threads, file, timeoutMs };
          }
          throw error;
        }
        const loadMs = Math.round(performance.now() - createStarted);

        const medianOf = (walls) => [...walls].sort((a, b) => a - b)[Math.floor(walls.length / 2)];
        // 单解码路径计时：REPEATS+1 次（首趟暖机不计入样本），从原文到该
        // 模式的最终输出全程入钟；两种模式各测各的，互不扣除。
        const timePath = async (path) => {
          const walls = [];
          let last = null;
          for (let run = 0; run < repeats + 1; run += 1) {
            const started = performance.now();
            last = await path();
            const wall = performance.now() - started;
            if (run > 0) walls.push(Math.round(wall * 1000) / 1000);
          }
          return { median: medianOf(walls), last };
        };

        const runCase = async (batch, entry, withTokens) => {
          const text = entry.text;
          const paths = {
            greedy: await timePath(() => infer(session, text).then((r) => greedyFromLogits(text, r))),
            constrained: await timePath(() => infer(session, text).then((r) => constrainedFromLogits(text, r))),
          };
          const goldSpans = {
            ITEM: entry.item !== null ? [text.indexOf(entry.item), text.indexOf(entry.item) + entry.item.length] : null,
            TGT: entry.target !== null ? [text.indexOf(entry.target), text.indexOf(entry.target) + entry.target.length] : null,
          };
          const fieldScore = (expected, span) => {
            if (expected === null && span === null) return { strict: true, loose: true };
            if (expected !== null && span !== null) {
              const strict = span[0] === text.indexOf(expected) && span[1] === span[0] + expected.length;
              const loose = span[0] < text.indexOf(expected) + expected.length && text.indexOf(expected) < span[1];
              return { strict, loose };
            }
            return { strict: false, loose: false };
          };

          // 逐 token 金标投影（两种解码共用）。
          const goldTokenTag = (tokenStart, tokenEnd) => {
            const mid = (tokenStart + tokenEnd) >>> 1;
            for (const name of ["ITEM", "TGT"]) {
              const span = goldSpans[name];
              if (span !== null && span[0] <= mid && mid < span[1]) {
                return `${mid === span[0] ? "B" : "I"}-${name}`;
              }
            }
            return "O";
          };
          // 概率取自约束路径的落盘运行（同一文本同一 logits，确定性推理
          // 下与贪心路径逐位一致）。
          const buildTokenRows = (ids) => {
            const rows = [];
            for (let index = 1; index < paths.greedy.last.offsets.length; index += 1) {
              const [tokenStart, tokenEnd] = paths.greedy.last.offsets[index];
              if (tokenEnd === 0) continue; // [SEP]
              const goldTag = goldTokenTag(tokenStart, tokenEnd);
              rows.push({
                start: tokenStart,
                end: tokenEnd,
                ch: text.slice(tokenStart, tokenEnd),
                gold: goldTag,
                pred: tags[ids[index]] ?? "O",
                pPred: Math.round(paths.constrained.last.probs[index][ids[index]] * 10000) / 10000,
                pGold: Math.round(paths.constrained.last.probs[index][tags.indexOf(goldTag)] * 10000) / 10000,
              });
            }
            return rows;
          };

          const row = { batch, group: entry.group ?? null, text, expectItem: entry.item, expectTarget: entry.target };
          const greedyTokenRows = buildTokenRows(paths.greedy.last.tagIds);
          for (const mode of Object.keys(paths)) {
            const d = paths[mode].last;
            const itemScore = fieldScore(entry.item, d.itemSpan);
            const targetScore = fieldScore(entry.target, d.targetSpan);
            const tokenRows = mode === "greedy" ? greedyTokenRows : buildTokenRows(d.ids);
            const sub = {
              predItem: d.predItem,
              predTarget: d.predTarget,
              itemSpan: d.itemSpan,
              targetSpan: d.targetSpan,
              itemStrict: itemScore.strict,
              itemLoose: itemScore.loose,
              targetStrict: targetScore.strict,
              targetLoose: targetScore.loose,
              diagnosis: {
                item: diagnoseField(text, goldSpans.ITEM, d.itemSpan, goldSpans.TGT, tokenRows, "ITEM", "TGT"),
                target: diagnoseField(text, goldSpans.TGT, d.targetSpan, goldSpans.ITEM, tokenRows, "TGT", "ITEM"),
              },
            };
            row[mode] = sub;
          }
          // 逐字记录（dev 批）：五类概率全存（顺序即 tags 数组）。
          if (withTokens) {
            row.tokens = greedyTokenRows.map((t) => ({
              ...t,
              probs: paths.constrained.last.probs[paths.constrained.last.offsets.findIndex((o) => o[0] === t.start && o[1] === t.end)]
                .map((p) => Math.round(p * 10000) / 10000),
            }));
          }
          row.wallMs = { greedy: paths.greedy.median, constrained: paths.constrained.median };
          row.withinTarget = {
            greedy: paths.greedy.median <= targetMs,
            constrained: paths.constrained.median <= targetMs,
          };
          return row;
        };

        const coldStarted = performance.now();
        const coldText = batches.find((b) => b.name === "scored").rows[0].text;
        await infer(session, coldText).then((r) => greedyFromLogits(coldText, r));
        const coldMs = Math.round(performance.now() - coldStarted);

        const cases = [];
        for (const batch of batches) {
          for (const entry of batch.rows) {
            cases.push(await runCase(batch.name, entry, batch.tokens));
          }
        }

        return {
          status: "ok",
          threads,
          file,
          loadMs,
          coldMs,
          cases,
        };
      },
      {
        modelDir: MODEL_DIR,
        tags: TAGS,
        classOrder: CLASS_ORDER,
        batches,
        threads: armConfig.threads,
        file: armConfig.file,
        repeats: REPEATS,
        targetMs: TARGET_MS,
        timeoutMs: CREATE_TIMEOUT_MS,
      },
    );
    await armPage.close();
    arms.push({ name: armConfig.name, ...arm });
    log(`${armConfig.name}: ${arm.status === "ok" ? `load=${arm.loadMs}ms cold=${arm.coldMs}ms` : arm.status}`);
  }
  await browser.close();

  const scoredArms = arms.filter((arm) => arm.status === "ok");
  const batchNames = batches.map((b) => b.name);
  const MODES = ["greedy", "constrained"];
  const rate = (arm, batch, mode, field) => {
    const rows = arm.cases.filter((row) => row.batch === batch);
    return `${rows.filter((row) => row[mode][`${field}Strict`]).length}/${rows.length}`;
  };
  const bothRate = (arm, batch, mode) => {
    const rows = arm.cases.filter((row) => row.batch === batch);
    return `${rows.filter((row) => row[mode].itemStrict && row[mode].targetStrict).length}/${rows.length}`;
  };
  for (const arm of scoredArms) {
    for (const mode of MODES) {
      const parts = batchNames.map((batch) => `${batch} ITEM ${rate(arm, batch, mode, "item")} TGT ${rate(arm, batch, mode, "target")} both ${bothRate(arm, batch, mode)}`);
      log(`${arm.name} ${mode}: ${parts.join(" | ")}`);
    }
    const medianWall = (mode) => arm.cases.map((row) => row.wallMs[mode]).sort((a, b) => a - b)[Math.floor(arm.cases.length / 2)];
    log(`${arm.name} timing: ${MODES.map((mode) => `${mode} medianWall=${medianWall(mode)}ms`).join(", ")} (each end-to-end text->output)`);
  }
  const primary = scoredArms[0] ?? { cases: [] };

  // 两臂逐例差异（预测级，不只 strict 位）：同分可以掩盖不同错误。
  const armDiffs = [];
  if (scoredArms.length === 2) {
    const [a, b] = scoredArms;
    for (let i = 0; i < a.cases.length; i += 1) {
      const ra = a.cases[i];
      const rb = b.cases[i];
      const differs = MODES.some(
        (mode) => ra[mode].predItem !== rb[mode].predItem || ra[mode].predTarget !== rb[mode].predTarget,
      );
      if (differs) {
        armDiffs.push({
          batch: ra.batch,
          group: ra.group,
          text: ra.text,
          expectItem: ra.expectItem ?? null,
          arms: Object.fromEntries(scoredArms.map((arm) => [arm.name, {
            greedy: [arm.cases[i].greedy.predItem, arm.cases[i].greedy.predTarget],
            constrained: [arm.cases[i].constrained.predItem, arm.cases[i].constrained.predTarget],
          }])),
        });
      }
    }
    log(`arm prediction diffs: ${armDiffs.length} case(s)`);
    for (const diff of armDiffs) {
      const q = diff.arms["q8-t1"];
      const f = diff.arms["fp32-t1"];
      log(`  [${diff.batch}] ${diff.text} q8=${q.greedy.join("/")} fp32=${f.greedy.join("/")} | constrained q8=${q.constrained.join("/")} fp32=${f.constrained.join("/")}`);
    }
  }

  // 错误类别聚合（多标签；dev 批；主臂 q8；两种解码分开统计）。
  const devDiagnostics = {};
  for (const batch of ["devClassic", "devGroups"]) {
    devDiagnostics[batch] = {};
    for (const mode of MODES) {
      devDiagnostics[batch][mode] = {};
      for (const field of ["item", "target"]) {
        const counts = {};
        for (const row of primary.cases.filter((r) => r.batch === batch)) {
          for (const cls of row[mode].diagnosis?.[field] ?? ["n/a"]) {
            counts[cls] = (counts[cls] ?? 0) + 1;
          }
        }
        devDiagnostics[batch][mode][field] = counts;
      }
    }
    for (const mode of MODES) {
      log(`${batch} ${mode} errors: item ${JSON.stringify(devDiagnostics[batch][mode].item)} target ${JSON.stringify(devDiagnostics[batch][mode].target)}`);
    }
  }

  // 解码对照汇总（两臂不合并，逐臂分列）。
  const decodingComparison = {};
  for (const arm of scoredArms) {
    decodingComparison[arm.name] = {};
    for (const batch of batchNames) {
      decodingComparison[arm.name][batch] = {};
      for (const mode of MODES) {
        decodingComparison[arm.name][batch][mode] = {
          itemStrict: rate(arm, batch, mode, "item"),
          targetStrict: rate(arm, batch, mode, "target"),
          bothFieldsCorrect: bothRate(arm, batch, mode),
        };
      }
    }
  }

  // 解码逐例得失（贪心->约束，两字段 strict 整句翻转，按臂×批分列）+
  // 空字段误报（期望为空、预测非空，含预测文本）：合并率会掩盖此消彼长，
  // 收益与代价都要逐句可核对。
  const decodeFlips = {};
  for (const arm of scoredArms) {
    decodeFlips[arm.name] = {};
    for (const batch of batchNames) {
      const rows = arm.cases.filter((row) => row.batch === batch);
      const gains = [];
      const losses = [];
      for (const row of rows) {
        const wasRight = row.greedy.itemStrict && row.greedy.targetStrict;
        const nowRight = row.constrained.itemStrict && row.constrained.targetStrict;
        if (wasRight === nowRight) continue;
        (nowRight ? gains : losses).push({
          text: row.text,
          group: row.group,
          expectItem: row.expectItem,
          expectTarget: row.expectTarget,
          greedy: { predItem: row.greedy.predItem, predTarget: row.greedy.predTarget },
          constrained: { predItem: row.constrained.predItem, predTarget: row.constrained.predTarget },
        });
      }
      const emptyFieldFalsePositives = Object.fromEntries(MODES.map((mode) => [mode, rows.flatMap((row) => {
        const fps = [];
        for (const [field, expect, pred] of [
          ["ITEM", row.expectItem, row[mode].predItem],
          ["TGT", row.expectTarget, row[mode].predTarget],
        ]) {
          if (expect === null && pred !== null) fps.push({ text: row.text, group: row.group, field, pred });
        }
        return fps;
      })]));
      decodeFlips[arm.name][batch] = { gains, losses, emptyFieldFalsePositives };
    }
  }
  for (const arm of scoredArms) {
    for (const batch of batchNames) {
      const f = decodeFlips[arm.name][batch];
      const gFps = f.emptyFieldFalsePositives.greedy;
      const cFps = f.emptyFieldFalsePositives.constrained;
      log(`${arm.name} ${batch} flips: greedy->constrained +${f.gains.length}/-${f.losses.length}, empty-field FP ${gFps.length}->${cFps.length}`);
      const fmt = (p) => `${p.predItem ?? "∅"}/${p.predTarget ?? "∅"}`;
      for (const [label, list] of [["gain", f.gains], ["loss", f.losses]]) {
        for (const item of list) {
          log(`  ${label}: ${item.text} gold=${item.expectItem ?? "∅"}/${item.expectTarget ?? "∅"} greedy=${fmt(item.greedy)} -> constrained=${fmt(item.constrained)}`);
        }
      }
      for (const fp of cFps) {
        if (!gFps.some((g) => g.text === fp.text && g.field === fp.field)) {
          log(`  new empty-field FP: ${fp.field}=${fp.pred} in ${fp.text}`);
        }
      }
    }
  }

  // 预注册验收判定：封存批每字段 strict >= 90% 且端到端 <= 4s；dev 批只
  // 作诊断。未传 --with-acceptance 时判定记 not-evaluated（批未加载）。
  let gate;
  if (evalAcceptance) {
    const acceptanceRows = primary.cases.filter((row) => row.batch === "acceptance");
    // 评分与计时读同一被验收模式（ACCEPTED_DECODE），不硬编码具体解码名。
    const m = ACCEPTED_DECODE;
    gate = {
      evaluated: true,
      decodeMode: m,
      itemStrictRate: `${acceptanceRows.filter((row) => row[m].itemStrict).length}/${acceptanceRows.length}`,
      targetStrictRate: `${acceptanceRows.filter((row) => row[m].targetStrict).length}/${acceptanceRows.length}`,
      itemPass: acceptanceRows.filter((row) => row[m].itemStrict).length / acceptanceRows.length >= 0.9,
      targetPass: acceptanceRows.filter((row) => row[m].targetStrict).length / acceptanceRows.length >= 0.9,
      bothFieldsCorrectRate: `${acceptanceRows.filter((row) => row[m].itemStrict && row[m].targetStrict).length}/${acceptanceRows.length}`,
      latencyAllWithinTarget: primary.cases.every((row) => row.withinTarget[m]),
      verdict: null,
    };
    gate.verdict = gate.itemPass && gate.targetPass && gate.latencyAllWithinTarget ? "accepted" : "rejected";
    log(`pre-registered gate: ITEM ${gate.itemStrictRate} TGT ${gate.targetStrictRate} both ${gate.bothFieldsCorrectRate} -> ${gate.verdict}`);
  } else {
    gate = {
      evaluated: false,
      decodeMode: ACCEPTED_DECODE,
      note: "sealed acceptance batch was NOT loaded or evaluated (protocol: single-shot via --with-acceptance after dev justifies it); gates: per-field strict >= 90% AND e2e <= 4s on that batch, scored AND timed on decodeMode",
      perBatchBothFieldsCorrect: Object.fromEntries(batchNames.map((batch) => [batch, scoredArms[0] ? bothRate(scoredArms[0], batch, ACCEPTED_DECODE) : "0/0"])),
      verdict: "not-evaluated",
    };
    log(`gate: not-evaluated (sealed); dev/scored ${ACCEPTED_DECODE} both-fields: ${JSON.stringify(gate.perBatchBothFieldsCorrect)}`);
  }

  const outDir = path.join(frontendRoot, "..", "artifacts", "benchmark");
  await mkdir(outDir, { recursive: true });
  const outPath = path.join(outDir, `labeler-trial-${Date.now()}-spans.json`);
  await writeFile(
    outPath,
    JSON.stringify(
      {
        hostCpu: cpu,
        task: "span-labeling",
        data: {
          file: path.relative(frontendRoot, MANIFEST_PATH),
          sha256: dataSha,
          counts: manifest.counts,
          acceptanceProtocol: manifest.acceptanceProtocol,
          batchSemantics: manifest.batchSemantics ?? null,
          attributionNote: manifest.attributionNote,
        },
        model: {
          dir: MODEL_DIR,
          base: "hfl/minirbt-h256 (~10.4M params, token-classification head)",
          files: modelFiles,
        },
        runtime: {
          userAgent,
          crossOriginIsolated: isolated,
          timingScope: "end-to-end per decode mode: raw text -> tokenize -> feed -> run -> post-process -> substrings; greedy (argmax+span decode) and constrained (softmax+enumeration) each timed over REPEATS+1 runs with median per case",
          threadNote: "single-thread only; >1-thread wasm session create hangs in this environment",
        },
        decodingMode: ACCEPTED_DECODE,
        targetMs: TARGET_MS,
        repeatsPerCase: REPEATS,
        errorTaxonomy: manifest.errorTaxonomy,
        decodingComparison,
        decodeFlips,
        devDiagnostics,
        armDiffs,
        acceptance: {
          evaluated: evalAcceptance,
          sealedSentences: manifest.acceptance.reduce((n, g) => n + g.sentences.length, 0),
          gate,
        },
        arms: scoredArms,
        exportedAt: new Date().toISOString(),
      },
      null,
      2,
    ),
  );
  log(`saved: ${outPath}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
